/* Ensure hidden attribute works correctly */
[hidden] {
  display: none !important;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-color: #2b2b38;
  --machine-body: #d9455f;
  --machine-shadow: #991f3d;
  --screen-bg: #111e25;
  --screen-text: #5af07b;
  --screen-warn: #fbd043;
  --snack-bg: #f7ebe1;
  --snack-border: #4a2828;
  --btn-gold: #ebb128;
  --btn-gold-shadow: #a8760c;
  --text-dark: #221b1b;
}

body {
  font-family: "Courier New", Courier, monospace, monospace;
  font-size: 16px;
  background-color: var(--bg-color);
  color: var(--text-dark);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.machine-container {
  background: var(--machine-body);
  border: 4px solid var(--text-dark);
  box-shadow: 8px 8px 0px 0px rgba(0, 0, 0, 0.4),
              inset -6px -6px 0px 0px var(--machine-shadow);
  border-radius: 4px;
  width: 100%;
  max-width: 440px;
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.machine-header h1 {
  font-size: 1.25rem;
  text-align: center;
  color: #fff;
  text-transform: uppercase;
  letter-spacing: 2px;
  text-shadow: 2px 2px 0 var(--text-dark);
}

/* Screen Panel */
.screen-panel {
  background-color: var(--screen-bg);
  border: 4px solid var(--text-dark);
  padding: 12px 14px;
  box-shadow: inset 3px 3px 0 0 rgba(0, 0, 0, 0.7);
}

.screen-row {
  display: flex;
  justify-content: space-between;
  font-size: 1.2rem;
  font-weight: bold;
  color: var(--screen-text);
  margin-bottom: 8px;
}

.message-box {
  font-size: 0.95rem;
  color: var(--screen-warn);
  min-height: 24px;
  word-break: break-word;
}

/* Snack Grid */
.snack-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.snack-btn {
  background: var(--snack-bg);
  border: 3px solid var(--snack-border);
  box-shadow: 4px 4px 0 0 var(--text-dark);
  padding: 12px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  font-family: inherit;
  font-weight: bold;
  transition: transform 0.05s ease;
}

.snack-btn:hover {
  background: #fff8f0;
}

.snack-btn:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

.snack-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 0 var(--text-dark);
}

.snack-name {
  font-size: 0.95rem;
  color: var(--text-dark);
}

.snack-price {
  font-size: 1rem;
  color: #a31d1d;
}

/* Pixel Icons (Pure CSS) */
.snack-icon {
  width: 24px;
  height: 32px;
  position: relative;
}

.icon-soda {
  background: #3978a8;
  border-radius: 2px 2px 4px 4px;
  border: 2px solid var(--text-dark);
}
.icon-soda::before {
  content: "";
  position: absolute;
  top: 6px;
  left: 2px;
  right: 2px;
  height: 8px;
  background: #ef476f;
}

.icon-chips {
  background: #ffd166;
  border-radius: 3px;
  border: 2px solid var(--text-dark);
}
.icon-chips::before {
  content: "";
  position: absolute;
  top: 10px;
  left: 3px;
  right: 3px;
  height: 4px;
  background: #e76f51;
}

.icon-candy {
  background: #06d6a0;
  border-radius: 6px;
  border: 2px solid var(--text-dark);
  height: 20px;
  margin-top: 6px;
}

.icon-bar {
  background: #8b5a2b;
  border: 2px solid var(--text-dark);
  height: 18px;
  margin-top: 8px;
}
.icon-bar::before {
  content: "";
  position: absolute;
  left: 2px;
  top: 2px;
  width: 8px;
  height: 10px;
  background: #ba8c63;
}

/* Coin Controls */
.controls-panel {
  display: flex;
  gap: 12px;
}

.coin-btn {
  flex: 1;
  background: var(--btn-gold);
  border: 3px solid var(--text-dark);
  box-shadow: 0 4px 0 0 var(--btn-gold-shadow),
              0 4px 0 3px var(--text-dark);
  color: var(--text-dark);
  font-family: inherit;
  font-weight: bold;
  font-size: 1rem;
  padding: 12px 6px;
  cursor: pointer;
  transition: transform 0.05s ease;
}

.coin-btn:hover {
  background: #fcd34d;
}

.coin-btn:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

.coin-btn:active {
  transform: translateY(4px);
  box-shadow: 0 0 0 0 var(--btn-gold-shadow),
              0 0 0 3px var(--text-dark);
}

/* Dispenser Chute */
.dispense-chute {
  background: #1e1e24;
  border: 4px solid var(--text-dark);
  padding: 14px;
  box-shadow: inset 0 6px 0 0 rgba(0, 0, 0, 0.6);
}

.chute-opening {
  text-align: center;
  min-height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.dispensed-item {
  color: #a0aec0;
  font-size: 0.95rem;
  font-weight: bold;
}

.dispensed-item.active {
  color: #fff;
  animation: dropIn 0.2s ease-out;
}

@keyframes dropIn {
  0% {
    transform: translateY(-8px);
    opacity: 0;
  }
  100% {
    transform: translateY(0);
    opacity: 1;
  }
}

/* Viewport adjustments */
@media (max-width: 360px) {
  .machine-container {
    padding: 16px 12px;
  }
  .snack-btn {
    padding: 8px 4px;
  }
  .coin-btn {
    font-size: 0.9rem;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  let creditCents = 0;

  // Elements
  const creditDisplay = document.getElementById('credit-display');
  const messageBox = document.getElementById('message-box');
  const dispensedItem = document.getElementById('dispensed-item');
  const btnInsert25 = document.getElementById('btn-insert-25');
  const btnInsert100 = document.getElementById('btn-insert-100');
  const snackButtons = document.querySelectorAll('.snack-btn');

  function formatCurrency(cents) {
    return '$' + (cents / 100).toFixed(2);
  }

  function updateCreditDisplay() {
    creditDisplay.textContent = formatCurrency(creditCents);
  }

  function addCredit(cents) {
    creditCents += cents;
    updateCreditDisplay();
    messageBox.textContent = `Added ${formatCurrency(cents)}. Credit: ${formatCurrency(creditCents)}`;
  }

  function handleSnackClick(event) {
    const button = event.currentTarget;
    const snackName = button.getAttribute('data-name');
    const priceCents = parseInt(button.getAttribute('data-price'), 10);

    if (creditCents >= priceCents) {
      const changeCents = creditCents - priceCents;
      creditCents = 0;
      updateCreditDisplay();

      messageBox.textContent = `Dispensed ${snackName}! Change: ${formatCurrency(changeCents)}`;
      dispensedItem.textContent = `* ${snackName} *`;
      dispensedItem.classList.add('active');
    } else {
      messageBox.textContent = 'Not enough credit';
    }
  }

  // Attach coin insertion listeners
  btnInsert25.addEventListener('click', () => addCredit(25));
  btnInsert100.addEventListener('click', () => addCredit(100));

  // Attach snack selection listeners
  snackButtons.forEach((btn) => {
    btn.addEventListener('click', handleSnackClick);
  });
});
